package io.knowledgebrain.planning;
import java.time.*;import java.util.*;
import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ReminderApiTest {
    ReminderStore store;SpaceAuthorizationClient auth;ReminderController api;UUID space,id,actor,schedule;String input;
    @BeforeEach void init(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();schedule=ids.next();store=mock(ReminderStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenReturn(actor);api=new ReminderController(store,auth,new SimpleMeterRegistry(),"https://localhost:8443");input="{\"scheduleId\":\""+schedule+"\",\"scheduleVersion\":1,\"minutesBefore\":10}";}
    MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/reminders");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
    ReminderStore.Reminder value(){return new ReminderStore.Reminder(id,space,"PRIVATE","ACTIVE",1,new ReminderRules.Input(schedule,1,10),null,"2028-01-01T00:00:00Z","2028-01-01T00:00:00","Z","b".repeat(64),Instant.now().toString(),Instant.now().toString());}
    String body(){return "{\"input\":"+input+",\"previewHash\":\""+"b".repeat(64)+"\"}";}
    @Test void everyReadAndPreviewChecksFreshPrivateScheduleAuthority()throws Exception{when(store.get(space,id)).thenReturn(value());for(int n=0;n<2;n++){var response=api.get(space.toString(),id.toString(),r("GET",null));assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals("\"rm1\"",response.getHeaders().getETag());}api.preview(space.toString(),r("POST",input));verify(auth,times(3)).authorize(eq(space),any(),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());reset(store);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.history(space.toString(),id.toString(),r("GET",null)));verifyNoInteractions(store);}
    @Test void strictJsonRejectsUnknownDuplicateTrailingFractionalAndOverflowedFields()throws Exception{for(String bad:List.of(input+" {}",input.replace("\"minutesBefore\":10","\"minutesBefore\":10,\"minutesBefore\":20"),input.replace(":10}",":10.0}"),input.replace(":10}",":4294967306}"),input.replace("\"scheduleVersion\":1","\"scheduleVersion\":9223372036854775808"),input.replace(":10}",":-1}"),input.substring(0,input.length()-1)+",\"actorId\":null}"))assertThrows(ResponseStatusException.class,()->api.preview(space.toString(),r("POST",bad)));verifyNoInteractions(store);}
    @Test void independentStrongVersionAndSingleCreateKeyAreRequired()throws Exception{assertEquals(428,assertThrows(ResponseStatusException.class,()->api.update(space.toString(),id.toString(),r("PUT",body()))).getStatusCode().value());for(String tag:List.of("\"sc1\"","\"rm0\"","\"rm01\"","W/\"rm1\"","*","\"rm9223372036854775808\"")){var req=r("PUT",body());req.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.update(space.toString(),id.toString(),req));}assertThrows(ResponseStatusException.class,()->api.create(space.toString(),r("POST",body())));var dup=r("POST",body());dup.addHeader("Idempotency-Key","c".repeat(32));dup.addHeader("Idempotency-Key","d".repeat(32));assertThrows(ResponseStatusException.class,()->api.create(space.toString(),dup));var good=r("POST",body());good.addHeader("Idempotency-Key","c".repeat(32));when(store.create(eq(space),eq(actor),eq("c".repeat(32)),any(),eq("b".repeat(64)),anyString())).thenReturn(new ReminderStore.Creation(value(),true));assertEquals(200,api.create(space.toString(),good).getStatusCode().value());verify(auth,atLeastOnce()).authorize(eq(space),any(),eq("SCHEDULE_WRITE"),eq("PRIVATE"),anyString());}
    @Test void crossOriginPreviewEditsAmbiguousCredentialsAndReadBodiesAreDenied(){for(String method:List.of("POST","PUT","DELETE")){var req=r(method,method.equals("DELETE")?null:body());req.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->{if(method.equals("POST"))api.preview(space.toString(),req);else if(method.equals("PUT"))api.update(space.toString(),id.toString(),req);else api.retire(space.toString(),id.toString(),req);}).getStatusCode().value());}var cookies=r("GET",null);cookies.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertEquals(401,assertThrows(ResponseStatusException.class,()->api.list(space.toString(),cookies)).getStatusCode().value());var dup=r("GET",null);dup.addParameter("state","ACTIVE","RETIRED");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),dup));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),r("GET","{}")));verifyNoInteractions(store);}
    @Test void httpErrorsRetainNoStoreAndPreconditionStatus()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(api).setControllerAdvice(new GoalErrors()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/spaces/"+space+"/reminders/"+id).secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").contentType("application/json").content(body())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(428)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control","no-store"));}
}
